public partial class MainForm {
 ComboBox aiMode=new ComboBox();CheckBox aiFixShort=new CheckBox();AiRepairSession pendingAi;string pendingAiSnapshot="";
 Button AiEntry(bool queued){var b=Btn("AI nâng cao",async(s,e)=>await OpenAiTimeline(queued));extraControls.Add(b);return b;}
 void BuildAiTools(FlowLayoutPanel parent){AddLabel(parent,"AI SỬA LỜI OFFLINE",true);aiMode.DropDownStyle=ComboBoxStyle.DropDownList;aiMode.Width=320;aiMode.Items.AddRange(new object[]{"Tắt · giữ lời, chỉ căn tốc độ","Đề xuất · duyệt trong AI nâng cao","Tự sửa có giới hạn · khi Tạo voice"});aiMode.SelectedIndex=0;parent.Controls.Add(aiMode);aiFixShort.Text="Đề xuất sửa cả câu quá ngắn";aiFixShort.Checked=true;aiFixShort.AutoSize=true;parent.Controls.Add(aiFixShort);parent.Controls.Add(AiEntry(false));AddLabel(parent,"AI dùng Qwen xử lý văn bản riêng. Gói model khoảng 2,5 GB, cài một lần. Hai lần sửa tối đa mỗi đơn vị. SRT Khóa / V15.6; vẫn cần duyệt nội dung.",false);extraControls.Add(aiMode);extraControls.Add(aiFixShort);aiMode.SelectedIndexChanged+=(s,e)=>{if(!restoring){UpdateShared();SaveSession();}};aiFixShort.CheckedChanged+=(s,e)=>{if(!restoring)SaveSession();};}
 Func<string,KokoroEngine> AiFactory(VoiceSettings settings){var first=catalog.Get(settings.Key);var second=settings.TwoVoices?catalog.Get(settings.VoiceBKey):first;string appRoot=root,cache=stateDir;Action<string> device=ShowDevice,activity=ShowActivity;int threads=Math.Max(1,Math.Min(4,Environment.ProcessorCount));return role=>{var p=role=="B"?second:first;if(String.IsNullOrEmpty(p.Name))throw new Exception("Giọng "+role+" không còn trong thư viện. Chọn lại trước khi sửa.");return new KokoroEngine{Root=appRoot,Speaker=p.Speaker,Kind=p.Kind,ModelFolder=p.ModelFolder,VoiceName=p.Name,ReferencePath=p.ReferencePath,ReferenceText=p.ReferenceText,DeviceMode=settings.Device,DeviceChanged=device,ActivityChanged=activity,Archive=new SpeechArchive(cache),Threads=threads};};}
 string AiVoiceFingerprint(VoiceSettings s,Func<string,KokoroEngine> factory){using(var a=factory("A")){string key=SpeechArchive.Key(a,"ai-profile",s.Speed);if(s.TwoVoices)using(var b=factory("B"))key+="|"+SpeechArchive.Key(b,"ai-profile",s.Speed);if(s.Breathing==1)key+="|breath:"+(File.Exists(s.BreathPath)?StateFiles.Hash(s.BreathPath):"missing");else if(s.Breathing==0){string folder=Path.Combine(a.Root,"breaths");key+="|breaths:"+(Directory.Exists(folder)?String.Join("|",Directory.GetFiles(folder,"*.wav").OrderBy(x=>x).Select(StateFiles.Hash)):"missing");}return key;}}
 async Task OpenAiTimeline(bool queued){if(busy)return;try{if(queued){if(jobGrid.CurrentRow==null)throw new Exception("Chọn một file SRT trong hàng đợi trước.");EditQueued();}ReadGrid();if(proseInput||mode.SelectedIndex==1)throw new Exception("AI sửa timeline dùng SRT Khóa hoặc V15.6. TXT tự nhiên vẫn tạo voice như hiện tại.");SpeakerScript.ValidateRun(cues,TwoSpeakers);var settings=CaptureSettings();if(queued&&batchMode.SelectedIndex==3)settings.Mode=2;var factory=AiFactory(settings);var p=AiRepairSession.Open(sourcePath,cues,stateDir,settings,aiFixShort.Checked,AiVoiceFingerprint(settings,factory));if(player!=null)player.Stop();SetBusy(true);using(var dialog=new AiTimelineDialog(root,p,factory,new LocalAi(root,settings.Device))){dialog.ShowDialog(this);lastVoiceReport=p.Report;if(dialog.Applied){p.Validate();cues=p.Effective();pendingAi=p;pendingAiSnapshot=AiRepairSession.SnapshotHash(cues);lastOutput=null;openOutput.Enabled=false;readingLive=false;lastAnchorReport=null;if(editingJob!=null){editingJob.Cues=cues;editingJob.State=JobState.Queued;editingJob.AiReport=p.Report;editingJob.AiSnapshot=pendingAiSnapshot;editingJob.Warning="Đã áp dụng lời AI · cần tạo và kiểm tra WAV tổng";}Populate();SaveSession();status.Text="Đã áp dụng các đề xuất bạn chấp nhận; file nguồn giữ nguyên. Bấm Tạo voice để kiểm tra toàn bài.";}SetBusy(false);if(dialog.RenderAfterApply)await Export();}}catch(Exception ex){Error(ex);}finally{SetBusy(false);}}
 Func<List<Cue>,RenderOptions,string,KokoroEngine,Action<int,string>,List<Cue>> AutoAiPreparation(VoiceSettings snapshot){if(snapshot.AiMode!=2)return (input,options,source,owner,notify)=>input;string appRoot=root,state=stateDir;var factory=AiFactory(snapshot);string fingerprint=AiVoiceFingerprint(snapshot,factory);return (input,o,source,owner,notify)=>{if(snapshot.AiMode!=2||o.Prose||(!o.Locked&&!o.Anchored))return input;var s=VoiceSettings.From(snapshot.Xml());s.Mode=o.Anchored?2:0;s.AiMode=2;var p=AiRepairSession.Open(source,input,state,s,s.AiFixShort,fingerprint);o.AiRepair=p;o.AiReportPath=p.Report;owner.Archive=owner.Archive??new SpeechArchive(state);owner.ReleaseModels();AiTimeline.Run(p,new LocalAi(appRoot,s.Device),factory,()=>owner.Cancelled,notify,true);return p.Effective();};}
 void AttachAiHistory(RenderOptions o,List<Cue> input,BatchJob job){string hash=AiRepairSession.SnapshotHash(input);if(pendingAi!=null&&pendingAiSnapshot==hash){o.AiRepair=pendingAi;o.AiReportPath=pendingAi.Report;}else if(job!=null&&job.AiSnapshot==hash)o.AiReportPath=job.AiReport;}
}
public sealed class AiTimelineDialog:Form {
 readonly string root;readonly AiRepairSession session;readonly Func<string,KokoroEngine> factory;readonly ITextRewriter rewriter;readonly DataGridView grid=new DataGridView();readonly TextBox original=new TextBox(),proposed=new TextBox(),detail=new TextBox();readonly Label status=new Label();readonly FlowLayoutPanel actions=new FlowLayoutPanel();readonly Button stop=new Button();readonly CheckBox onlyProblems=new CheckBox();readonly List<AiRepairRow> visible=new List<AiRepairRow>();bool running;volatile bool cancelled;SoundPlayer player;KokoroEngine current;
 public bool Applied,RenderAfterApply;
 public AiTimelineDialog(string appRoot,AiRepairSession p,Func<string,KokoroEngine> engineFactory,ITextRewriter textRewriter){root=appRoot;session=p;factory=engineFactory;rewriter=textRewriter;Text="AI sửa timeline · Qwen offline · 2.0.14";Size=new Size(1260,860);MinimumSize=new Size(1080,740);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(244,247,251);
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=6};foreach(var h in new[]{60,110,0,230,80,34})layout.RowStyles.Add(new RowStyle(h==0?SizeType.Percent:SizeType.Absolute,h==0?100:h));Controls.Add(layout);layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="AI sửa đúng phần không đạt, giữ mốc và vai nói. Đề xuất đo đạt vẫn cần bạn duyệt ý nghĩa.\nGói AI: "+(LocalAi.Ready(root)?"Đã có model và bộ chạy":"Chưa sẵn sàng · tải hoặc nhập model GGUF trước khi đề xuất")+". Lời sửa không ghi vào SRT nguồn.",ForeColor=Color.FromArgb(19,31,52)},0,0);
  actions.Dock=DockStyle.Fill;actions.WrapContents=true;actions.AutoScroll=true;layout.Controls.Add(actions,0,1);Add("Đo & đề xuất",async()=>await RunWork(true,false));Add("Chấp nhận phần chọn",()=>{Accept(false);return Task.FromResult(0);});Add("Hoàn tác",()=>{Undo();return Task.FromResult(0);});Add("Nghe gốc",()=>{Play(false);return Task.FromResult(0);});Add("Nghe đề xuất",()=>{Play(true);return Task.FromResult(0);});Add("Cài gói AI",async()=>await Setup());
  var more=new Button{Text="Thêm ▾",AutoSize=true,MinimumSize=new Size(90,34)};var menu=new ContextMenuStrip();Action<string,Func<Task>> item=(title,action)=>{var m=new ToolStripMenuItem(title);m.Click+=async(s,e)=>{try{await action();}catch(Exception ex){status.Text=ex.Message;}};menu.Items.Add(m);};item("Chỉ đo · chưa gọi AI",async()=>await RunWork(false,false));item("Tự chấp nhận bản đo đạt",async()=>await RunWork(true,true));item("Chấp nhận tất cả bản đạt",()=>{Accept(true);return Task.FromResult(0);});item("Nhập model GGUF đã tải",async()=>await ImportModel());item("Đặt lại phần đang chọn",()=>{ResetRow();return Task.FromResult(0);});item("Mở báo cáo chi tiết",()=>{OpenReport();return Task.FromResult(0);});more.Click+=(s,e)=>menu.Show(more,new Point(0,more.Height));actions.Controls.Add(more);onlyProblems.Text="Chỉ hiện phần cần xử lý";onlyProblems.AutoSize=true;onlyProblems.CheckedChanged+=(s,e)=>RefreshRows();actions.Controls.Add(onlyProblems);
  grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.BackgroundColor=Color.White;foreach(string n in new[]{"#","Cue","Giọng","Khung s","Gốc s","Sửa s","Tốc độ","Trạng thái"})grid.Columns.Add(n,n);grid.Columns[0].Width=40;grid.Columns[1].Width=80;grid.Columns[2].Width=55;for(int i=3;i<=6;i++)grid.Columns[i].Width=85;grid.Columns[7].AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;grid.SelectionChanged+=(s,e)=>RefreshSelection();layout.Controls.Add(grid,0,2);
  var compare=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2,Margin=new Padding(0,10,0,0)};compare.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));compare.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));compare.RowStyles.Add(new RowStyle(SizeType.Absolute,27));compare.RowStyles.Add(new RowStyle(SizeType.Percent,100));compare.Controls.Add(new Label{Text="LỜI GỐC · giữ nguyên file nguồn",Dock=DockStyle.Fill},0,0);compare.Controls.Add(new Label{Text="LỜI ĐỀ XUẤT · chỉ áp dụng sau khi chấp nhận",Dock=DockStyle.Fill},1,0);foreach(var t in new[]{original,proposed}){t.Multiline=true;t.ReadOnly=true;t.ScrollBars=ScrollBars.Vertical;t.Dock=DockStyle.Fill;t.BackColor=Color.White;t.Font=new Font("Segoe UI",11);}compare.Controls.Add(original,0,1);compare.Controls.Add(proposed,1,1);layout.Controls.Add(compare,0,3);detail.Multiline=true;detail.ReadOnly=true;detail.ScrollBars=ScrollBars.Vertical;detail.Dock=DockStyle.Fill;detail.BackColor=Color.White;layout.Controls.Add(detail,0,4);
  var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true};layout.Controls.Add(bottom,0,5);var apply=new Button{Text="Áp dụng vào kịch bản",AutoSize=true};apply.Click+=(s,e)=>Apply(false);bottom.Controls.Add(apply);var render=new Button{Text="Áp dụng & tạo WAV",AutoSize=true};render.Click+=(s,e)=>Apply(true);bottom.Controls.Add(render);var export=new Button{Text="Xuất SRT đã sửa",AutoSize=true};export.Click+=(s,e)=>ExportSrt();bottom.Controls.Add(export);stop.Text="Dừng";stop.AutoSize=true;stop.Enabled=false;stop.Click+=(s,e)=>{cancelled=true;if(current!=null)current.Cancel();};bottom.Controls.Add(stop);status.AutoSize=true;status.MaximumSize=new Size(550,0);bottom.Controls.Add(status);Tag=bottom;FormClosing+=(s,e)=>{if(running){e.Cancel=true;cancelled=true;if(current!=null)current.Cancel();status.Text="Đang dừng; đóng lại sau khi tác vụ dừng.";}else if(player!=null)player.Dispose();};RefreshRows();
 }
 void Add(string title,Func<Task> action){var b=new Button{Text=title,AutoSize=true,Height=36,MinimumSize=new Size(100,34)};b.Click+=async(s,e)=>{try{await action();}catch(Exception ex){status.Text=ex.InnerException==null?ex.Message:ex.InnerException.Message;}};actions.Controls.Add(b);}
 AiRepairRow Selected{get{return grid.CurrentRow==null||grid.CurrentRow.Index>=visible.Count?null:visible[grid.CurrentRow.Index];}}
 void Busy(bool value){running=value;actions.Enabled=!value;grid.Enabled=!value;stop.Enabled=value;foreach(Control c in ((FlowLayoutPanel)Tag).Controls)if(c!=stop&&c!=status)c.Enabled=!value;UseWaitCursor=value;}
 void Activity(int percent,string text){if(IsDisposed)return;BeginInvoke((Action)(()=>{status.Text=text;RefreshRows();}));}
 async Task RunWork(bool generate,bool accept){if(running)return;cancelled=false;Busy(true);try{await Task.Run(()=>AiTimeline.Run(session,rewriter,role=>{current=factory(role);return current;},()=>cancelled,Activity,accept,generate));}catch(OperationCanceledException){status.Text="Đã dừng. Kết quả đã đo được giữ lại.";}catch(Exception ex){status.Text=ex.Message;}finally{current=null;Busy(false);RefreshRows();}}
 async Task Setup(){if(running)return;cancelled=false;Busy(true);try{await Task.Run(()=>LocalAi.Setup(root,()=>cancelled,m=>Activity(0,m)));status.Text="Đã cài gói AI · có thể dùng offline.";}catch(OperationCanceledException){status.Text="Đã dừng tải; gói chưa hoàn tất không được dùng.";}catch(Exception ex){status.Text="Chưa cài được gói AI: "+ex.Message;}finally{Busy(false);}}
 async Task ImportModel(){using(var d=new OpenFileDialog{Filter="Qwen3-4B-Instruct-2507 Q4_K_M|*.gguf"}){if(d.ShowDialog()!=DialogResult.OK)return;string file=d.FileName;cancelled=false;Busy(true);try{await Task.Run(()=>LocalAi.InstallModel(root,file,()=>cancelled));status.Text="Đã nhập model đã kiểm tra. Bộ chạy CPU/GPU cần được cài kèm.";}catch(Exception ex){status.Text=ex.Message;}finally{Busy(false);}}}
 void RefreshRows(){int old=Selected==null?0:Selected.Stage.Number;grid.Rows.Clear();visible.Clear();foreach(var r in session.Rows){if(onlyProblems.Checked&&r.Original!=null&&!r.Original.NeedsRepair&&r.Original.Error.Length==0)continue;visible.Add(r);var best=r.Best;int row=grid.Rows.Add(r.Stage.Number,String.Join(",",r.Stage.Cues.Select(c=>c.Id)),SpeakerScript.Role(r.Stage.Cues[0]),r.Stage.Budget.ToString("0.000"),r.Original==null?"chưa đo":r.Original.Error.Length>0?"lỗi":r.Original.Natural.ToString("0.000"),best==null?(r.Original!=null&&!r.Original.NeedsRepair&&r.Original.Error.Length==0?"giữ gốc":"chưa đạt"):best.Measurement.After.ToString("0.000"),best==null?(r.Original==null?"":r.Original.Speed.ToString("0.000")):best.Measurement.Speed.ToString("0.000"),r.Status);grid.Rows[row].DefaultCellStyle.BackColor=r.Chosen!=null?Color.FromArgb(225,245,235):r.Original!=null&&r.Original.NeedsRepair?Color.FromArgb(255,242,220):Color.White;if(r.Stage.Number==old)grid.CurrentCell=grid.Rows[row].Cells[0];}RefreshSelection();}
 void RefreshSelection(){var r=Selected;if(r==null){original.Text=proposed.Text=detail.Text="";return;}original.Text=String.Join("\r\n\r\n",r.Stage.Cues.Select(c=>"#"+c.Id+" · "+SpeakerScript.Tagged(c)));var a=r.Chosen??r.Best??r.Attempts.LastOrDefault(x=>x.Cues.Count>0);proposed.Text=a==null?"Chưa có đề xuất. Bấm Đo & đề xuất phần lỗi.":String.Join("\r\n\r\n",a.Cues.Select(c=>"#"+c.Id+" · "+SpeakerScript.Tagged(c)));detail.Text="Trạng thái: "+r.Status+"\r\nGốc: "+(r.Original==null?"chưa đo":r.Original.Error.Length>0?r.Original.Error:r.Original.Detail+" · "+r.Original.Natural.ToString("0.000")+"s → "+r.Original.After.ToString("0.000")+"s · "+r.Original.Speed.ToString("0.000")+"x")+"\r\nĐề xuất: "+(a==null?"chưa có":a.Measurement==null?a.Error:a.Measurement.Detail+" · "+a.Measurement.Natural.ToString("0.000")+"s → "+a.Measurement.After.ToString("0.000")+"s · "+a.Measurement.Speed.ToString("0.000")+"x")+"\r\nThử AI "+r.Attempts.Count+" / 2 · "+String.Join("; ",r.Attempts.Where(x=>x.Error.Length>0).Select(x=>x.Error));}
 void Accept(bool all){if(running)return;session.Validate();foreach(var r in all?session.Rows:new List<AiRepairRow>{Selected}.Where(x=>x!=null)){if(r.Best!=null)r.Accepted=r.Best.Number;}session.Save();RefreshRows();}
 void Undo(){if(running||Selected==null)return;Selected.Accepted=0;session.Save();RefreshRows();}
 void ResetRow(){if(running||Selected==null)return;Selected.Accepted=0;Selected.Attempts.Clear();Selected.Original=null;Selected.Error="";session.Save();RefreshRows();status.Text="Đã đặt lại phần đang chọn. Bấm Đo & đề xuất để thử lại.";}
 void Play(bool suggestion){if(running||Selected==null)return;var r=Selected;var a=r.Chosen??r.Best??r.Attempts.LastOrDefault(x=>x.Measurement!=null);var m=suggestion?(a==null?null:a.Measurement):r.Original;if(m==null||!m.Valid){status.Text="Phần này chưa có audio đo hợp lệ.";return;}string path=suggestion?m.Audio:m.NaturalAudio;if(player!=null)player.Dispose();player=new SoundPlayer(path);player.Load();player.Play();status.Text=suggestion?"Đang nghe bản đã căn của đề xuất":"Đang nghe bản gốc trước căn";}
 void Apply(bool render){if(running)return;session.Validate();session.Save();Applied=true;RenderAfterApply=render;DialogResult=DialogResult.OK;Close();}
 void OpenReport(){if(File.Exists(session.Report))Process.Start(new ProcessStartInfo(session.Report){UseShellExecute=true});}
 void ExportSrt(){if(running)return;session.Validate();string parent=String.IsNullOrEmpty(session.Source)?session.Folder:Path.GetDirectoryName(session.Source);string name=String.IsNullOrEmpty(session.Source)?"kich_ban.srt":Path.ChangeExtension(Path.GetFileName(session.Source),".srt");string dir=Path.Combine(parent,"V15_AI_SRT_"+DateTime.Now.ToString("yyyyMMdd_HHmmss_fff"));Directory.CreateDirectory(dir);string path=Path.Combine(dir,name);using(var file=new FileStream(path,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(file,new UTF8Encoding(false)))writer.Write(Scripts.ToSrt(session.Effective()));status.Text="Đã xuất SRT: "+path;}
}
